"""Test explicit fine gradients against original implicit normal samples."""
from pathlib import Path
import json,hashlib,struct,subprocess,sys
s=Path(__file__).parent;r=s.parents[1];w=Path('F:/OpenRPG_ImportWork');root=w/'townsmith-native-normal-fine-grad-carrier-v61';assert not root.exists()
def sha(p):
 with p.open('rb') as f:return hashlib.file_digest(f,'sha256').hexdigest()
parent=w/'townsmith-native-normal-bits-carrier-v59/SM_Door-Single-B.normal-bits.candidate.glb';proof=json.loads((parent.parent/'RESULT.v1.json').read_text());assert sha(parent)==proof['input_pins'][str(parent)]
raw=parent.read_bytes();n=struct.unpack_from('<I',raw,12)[0];doc=json.loads(raw[20:20+n]);prefix=raw[28+n:];binary=bytearray(prefix);c=doc['materials'][0]['extensions']['OPENRPG_source_graph'];v=doc['bufferViews'][c['forward']['buffer_view']];stage=prefix[v.get('byteOffset',0):v.get('byteOffset',0)+v['byteLength']];assert hashlib.sha256(stage).hexdigest()==c['forward']['sha256'];t=stage.decode()
a='let a=textureSample(t6,s6,uv);';b='let b=textureSample(t7,s7,uv*30.0);';assert t.count(a)==1 and t.count(b)==1
t=t.replace(a,'let a=textureSampleGrad(t6,s6,uv,dpdxFine(uv),dpdyFine(uv));').replace(b,'let detail_uv=uv*30.0;let b=textureSampleGrad(t7,s7,detail_uv,dpdxFine(detail_uv),dpdyFine(detail_uv));')
stage=t.encode();i=len(doc['bufferViews']);doc['bufferViews'].append(dict(buffer=0,byteOffset=len(binary),byteLength=len(stage)));binary.extend(stage);c['forward']=dict(buffer_view=i,sha256=hashlib.sha256(stage).hexdigest());binary.extend(b'\0'*(-len(binary)%4));doc['buffers'][0]['byteLength']=len(binary);doc.setdefault('extras',{})['private_normal_fine_gradient_control']=dict(mode='explicit_fine_gradients',installed_in_product=False,full_import=False)
j=json.dumps(doc,separators=(',',':')).encode();j+=b' '*(-len(j)%4);out=struct.pack('<III',0x46546c67,2,28+len(j)+len(binary))+struct.pack('<II',len(j),0x4e4f534a)+j+struct.pack('<II',len(binary),0x004e4942)+binary;assert binary[:len(prefix)]==prefix
root.mkdir();glb=root/'SM_Door-Single-B.normal-fine-grad.candidate.glb';glb.write_bytes(out);(root/'normal-fine-grad.forward.wgsl').write_bytes(stage)
q=s/'queue_source_glb_normal_fine_grad_v61.py';assert not q.exists();qt=(s/'queue_source_glb_normal_bits_v59.py').read_text(encoding='utf-8');qt=qt.replace('townsmith-native-normal-bits-channel-{CHANNEL}-v59','townsmith-native-normal-fine-grad-channel-{CHANNEL}-v61').replace('townsmith-native-normal-bits-carrier-v59/SM_Door-Single-B.normal-bits.candidate.glb','townsmith-native-normal-fine-grad-carrier-v61/SM_Door-Single-B.normal-fine-grad.candidate.glb').replace(sha(parent),sha(glb)).replace('townsmith-native-normal-bits-carrier-v59/RESULT.v1.json','townsmith-native-normal-fine-grad-carrier-v61/RESULT.v1.json');compile(qt,str(q),'exec');q.write_text(qt,encoding='utf-8')
runner=s/'run_townsmith_normal_fine_grad_v61.py';assert not runner.exists();rt=(s/'run_townsmith_normal_bits_v59.py').read_text(encoding='utf-8').replace('townsmith-native-normal-bits-batch-v59','townsmith-native-normal-fine-grad-batch-v61').replace('queue_source_glb_normal_bits_v59.py','queue_source_glb_normal_fine_grad_v61.py').replace('townsmith-native-normal-bits-channel-{channel}-v59','townsmith-native-normal-fine-grad-channel-{channel}-v61').replace('eight_native_normal_bit_channels_drawn_with_stable_readbacks','eight_native_normal_fine_grad_channels_drawn_with_stable_readbacks');compile(rt,str(runner),'exec');runner.write_text(rt,encoding='utf-8')
(root/'RESULT.v1.json').write_text(json.dumps(dict(status='private_explicit_fine_gradient_control_prepared',input_pins={str(p):sha(p) for p in [Path(__file__),parent,glb,q,runner]},original_binary_prefix_byte_equal=True,resources_unchanged=True,source_pixels_applied_to_native=False,installed_in_product=False,full_import=False),indent=2),encoding='utf-8')
